-- Notes and their links to the taxonomy. RLS on, no policies: the API is the only reader.
create type public.note_status as enum ('draft', 'todo', 'in_progress', 'done');
create type public.importance as enum ('important', 'not_important');
create type public.urgency as enum ('not_critical', 'medium', 'critical', 'urgent');

create table public.notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  -- Generated by the client; makes a retried create idempotent.
  client_id uuid not null,
  body text not null check (length(btrim(body)) > 0),
  status public.note_status not null default 'draft',
  importance public.importance,
  urgency public.urgency,
  due_date date,
  -- Claude's new category/tag names for a draft; cleared on submit.
  proposed jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (user_id, client_id)
);

create index notes_user_created_idx on public.notes (user_id, created_at desc)
  where deleted_at is null;

create table public.note_categories (
  note_id uuid not null references public.notes (id) on delete cascade,
  category_id uuid not null references public.categories (id) on delete cascade,
  primary key (note_id, category_id)
);
create index note_categories_category_idx on public.note_categories (category_id);

create table public.note_tags (
  note_id uuid not null references public.notes (id) on delete cascade,
  tag_id uuid not null references public.tags (id) on delete cascade,
  primary key (note_id, tag_id)
);
create index note_tags_tag_idx on public.note_tags (tag_id);

alter table public.notes enable row level security;
alter table public.note_categories enable row level security;
alter table public.note_tags enable row level security;
